#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
const long long ROOT = 3;

long long modExp(long long base, int exp) {
    long long result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

void fftTransform(vector<long long>& array, int length, int direction) {
    int n = length;
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j >= bit; bit >>= 1) j -= bit;
        j += bit;
        if (i < j) {
            swap(array[i], array[j]);
        }
    }
    for (int size = 2; size <= n; size <<= 1) {
        long long wlen = modExp(ROOT, (MOD - 1) / size);
        if (direction == -1) wlen = modExp(wlen, MOD - 2);
        for (int start = 0; start < n; start += size) {
            long long w = 1;
            for (int k = start; k < start + size / 2; k++) {
                long long u = array[k];
                long long v = array[k + size / 2] * w % MOD;
                array[k] = (u + v) % MOD;
                array[k + size / 2] = (u - v + MOD) % MOD;
                w = w * wlen % MOD;
            }
        }
    }
    if (direction == -1) {
        long long invN = modExp(n, MOD - 2);
        for (int i = 0; i < n; i++) {
            array[i] = array[i] * invN % MOD;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    int size = 1;
    int halfN = n / 2;
    while (size < (9 * halfN + 1)) size <<= 1;
    vector<long long> polyA(size, 0);
    vector<long long> polyB(size, 0);

    polyA[0] = 1;
    for (int i = 0; i < m; i++) {
        int x;
        cin >> x;
        polyB[x] = 1;
    }

    fftTransform(polyA, size, 1);
    fftTransform(polyB, size, 1);

    for (int i = 0; i < size; i++) {
        if (polyA[i] != 0 && polyB[i] != 0) {
            polyA[i] = polyA[i] * modExp(polyB[i], halfN) % MOD;
        } else {
            polyA[i] = 0;
        }
    }

    fftTransform(polyA, size, -1);

    long long totalSum = 0;
    for (int i = 0; i < size; i++) {
        totalSum = (totalSum + polyA[i] * polyA[i]) % MOD;
    }
    cout << totalSum << "\n";
    return 0;
}
